            {
              "title": "Spawning season and batch fecundity of Indian Mackerel, Rastrelliger kanagurta, Siquijor Province, Central Philippines: Implications for Sustainable Fisheries Management",
              "primary": false,
              "talk_id": "d776a57e-1d27-46df-b743-5a9c622563c5"
            }
