            {
              "title": "The impact and variability of bleaching across Lord Howe Island during the 2024 heat event.",
              "primary": false,
              "talk_id": "6e9fa701-5125-402a-80c9-b22a3a390364"
            },
            {
              "title": "The Response of Corallivorous Chaetodon butterflyfishes to Coral Bleaching in a Subtropical Lagoonal Reef",
              "primary": false,
              "talk_id": "b81227cf-9257-4b4f-b7fd-c6e68f2ace5a"
            }
